let teq_nosmt_force_phase1 (g : FStarC_Reflection_Types.env) (ty1 : FStarC_Reflection_Types.term) (ty2 : FStarC_Reflection_Types.term) : bool =
  (teq_nosmt_force (phase1 g) ty1 ty2)

let teq_nosmt_phase1 (g : FStarC_Reflection_Types.env) (ty1 : FStarC_Reflection_Types.term) (ty2 : FStarC_Reflection_Types.term) : bool =
  (ml_dv (fun tmp -> (let tmp1 = (FStarC_Errors.catch_errors (fun tmp1 -> (FStarC_TypeChecker_Rel.teq_nosmt (FStarC_TypeChecker_Env.set_range (phase1 g) (match ty1 with
      | { FStarC_Syntax_Syntax.n = n; pos = pos; hash_code = hash_code; _ } -> pos
    )) ty1 ty2))) in
  (match tmp1 with
    | (tmp2, res) -> (match res with
        | (Some ((Some (tmp3)))) -> true
        | tmp3 -> false
      )
  ))))

let new_implicit_var (reason : string) (r : FStarC_Range_Type.range) (g : FStarC_Reflection_Types.env) (e : FStarC_Reflection_Types.typ) (unrefine : bool) : FStarC_Reflection_Types.term =
  (ml_dv (fun tmp -> (let tmp1 = (FStarC_TypeChecker_Util.new_implicit_var reason r (phase1 g) e unrefine) in
  (match tmp1 with
    | (uvar, tmp2, tmp3) -> uvar
  ))))

let try_solve_single_valued_implicits (g : FStarC_Reflection_Types.env) (ts : (FStarC_Reflection_Types.term) list) : unit =
  (ml_dv (fun tmp -> (let imps = (BatList.filter_map (fun t -> (let t1 = (FStarC_Syntax_Subst.compress t) in
    (match (match t1 with
      | { FStarC_Syntax_Syntax.n = n; pos = pos; hash_code = hash_code; _ } -> n
    ) with
      | (FStarC_Syntax_Syntax.Tm_uvar (ctx_u, tmp1)) -> (Some ({ FStarC_TypeChecker_Common.imp_reason = "single-valued implicit";
          imp_uvar = ctx_u;
          imp_tm = t1;
          imp_range = (match t1 with
            | { FStarC_Syntax_Syntax.n = n; pos = pos; hash_code = hash_code; _ } -> pos
          ) }))
      | tmp1 -> None
    ))) ts) in
  (ignore (FStarC_TypeChecker_Rel.try_solve_single_valued_implicits (phase1 g) false imps));
  ())))

let get_error_bound (tmp : unit) (tmp1 : FStarC_Tactics_Types.ref_proofstate) : (FStarC_Range_Type.range) option =
  (!(FStarC_Errors.error_range_bound))

let with_error_bound (r : FStarC_Range_Type.range) (f : (unit -> (FStarC_Tactics_Types.ref_proofstate -> 'u___a))) : (FStarC_Tactics_Types.ref_proofstate -> 'u___a) =
  (fun ps -> (FStarC_Errors.with_error_bound r (fun tmp -> (run_tac f ps))))

let deep_compress (t : FStarC_Reflection_Types.term) : FStarC_Reflection_Types.term =
  (ml_tot (fun tmp -> (FStarC_Syntax_Compress.deep_compress_uvars t)))

let beta_lax (g : FStarC_Reflection_Types.env) (t : FStarC_Reflection_Types.term) : FStarC_Reflection_Types.term =
  (ml_tot (fun tmp -> (FStarC_TypeChecker_Normalize.normalize (FStarC_TypeChecker_Env.Unascribe :: (FStarC_TypeChecker_Env.Beta :: [])) g t)))

let print_context (c : (((string * (FStarC_Range_Type.range) option)) list) FStar_Sealed.sealed) (tmp : FStarC_Tactics_Types.ref_proofstate) : string =
  (let tmp1 = (BatList.map ctxt_elt_as_string c) in
  (BatString.concat "\n>" tmp1))

exception Quiet_failure

let try_quietly (f : (unit -> (FStarC_Tactics_Types.ref_proofstate -> 'u___a))) (ps : FStarC_Tactics_Types.ref_proofstate) : ('u___a) option =
  (let attempt = (fun ps1 -> (let tmp = (FStarC_Errors.catch_errors_aux (fun tmp -> (run_tac f ps1))) in
    (match tmp with
      | (errs, rest, r) -> (match (errs, r) with
          | ([], (Some (x))) -> ((FStarC_Errors.add_issues rest);
            (Obj.magic (x)))
          | tmp1 -> (raise Quiet_failure)
        )
    ))) in
  let tmp = (FStarC_Tactics_Monad.catch attempt ps) in
  (match tmp with
    | (FStar_Pervasives.Inr (x)) -> (let tmp1 = (Obj.magic (x)) in
      (Some (tmp1)))
    | (FStar_Pervasives.Inl (tmp1)) -> None
  ))

